import{_ as a,o as t,c as i,ai as n}from"./chunks/framework.Ba-VnP44.js";const _=JSON.parse('{"title":"个人智能体搭建入门","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/agent-basics.md","filePath":"ai/productivity/agent-basics.md"}'),l={name:"ai/productivity/agent-basics.md"};function r(s,e,o,g,d,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="个人智能体搭建入门" tabindex="-1">个人智能体搭建入门 <a class="header-anchor" href="#个人智能体搭建入门" aria-label="Permalink to “个人智能体搭建入门”">​</a></h1><h2 id="场景与问题" tabindex="-1">场景与问题 <a class="header-anchor" href="#场景与问题" aria-label="Permalink to “场景与问题”">​</a></h2><p>Agent 这词被炒得很热，但对个人使用者来说，它其实是个很朴素的结构：模型 + 工具 + 循环。你给模型一组工具（搜网页、读文件、调 API、执行命令），它根据目标自己决定调哪个、看结果、再决定下一步，循环直到完成或放弃。ChatGPT 的联网搜索就是个最小例子：判断需要搜索 → 调搜索工具 → 读结果 → 组织回答。</p><p>很多人搭不起来，是因为一上来就想做“全自动完成复杂任务的管家”，结果模型在第三步选错工具、第五步拿着错误结果一路狂奔，兜不住。个人搭 Agent 的正确姿势是：目标足够小、工具足够傻、兜底足够厚。这篇讲清楚这三件事怎么落地。</p><h2 id="做法" tabindex="-1">做法 <a class="header-anchor" href="#做法" aria-label="Permalink to “做法”">​</a></h2><h3 id="_1-先分清-工作流还是-agent" tabindex="-1">1. 先分清：工作流还是 Agent <a class="header-anchor" href="#_1-先分清-工作流还是-agent" aria-label="Permalink to “1. 先分清：工作流还是 Agent”">​</a></h3><ul><li><strong>工作流</strong>：步骤是预先编排好的，模型只负责每一步的内容生成。“收集输入 → 让模型分类 → 按分类走固定分支 → 模型总结”，这是工作流。</li><li><strong>Agent</strong>：步骤由模型在运行时自己决定，包括“下一步做什么”。</li></ul><p>判断标准就一条：<strong>流程能不能提前写死</strong>。能写死就写工作流——可预测、好调试、出问题知道去哪查。只有任务确实需要模型边做边判断（比如“查一个问题，根据查到的情况决定继续查还是收工”）才用 Agent。绝大多数个人场景，工作流就够了，别为了 Agent 而 Agent。</p><h3 id="_2-搭一个最小可用-agent" tabindex="-1">2. 搭一个最小可用 Agent <a class="header-anchor" href="#_2-搭一个最小可用-agent" aria-label="Permalink to “2. 搭一个最小可用 Agent”">​</a></h3><p>四件东西：</p><ul><li><strong>一个明确的单一目标</strong>：如“汇总某仓库今天的 issue 变化”，不是“帮我管理项目”。</li><li><strong>两三个边界清晰的工具</strong>：<code>search(query)</code>、<code>read_file(path)</code>、<code>send_message(text)</code>。工具越少，模型选错的概率越低。</li><li><strong>一个循环</strong>：模型输出动作 → 执行工具 → 结果塞回上下文 → 再来，直到模型给出“完成”或达到最大步数。</li><li><strong>一个系统提示</strong>：写明目标、允许用什么、禁止做什么、什么时候停。</li></ul><p>不用自己从零造轮子，各大模型的 Agent SDK、甚至一段百来行的 Python 循环都能起步。结构比框架重要——先把循环跑通，再谈工程化。</p><h3 id="_3-工具设计是成败关键" tabindex="-1">3. 工具设计是成败关键 <a class="header-anchor" href="#_3-工具设计是成败关键" aria-label="Permalink to “3. 工具设计是成败关键”">​</a></h3><ul><li><strong>名字和描述要像给实习生看的说明书</strong>：<code>read_file</code> 比 <code>rf</code> 好，描述里写清什么时候用、参数什么格式、返回什么。模型对工具的理解完全来自这段文字。</li><li><strong>返回值要带错误信息</strong>：文件不存在就返回“文件不存在：/xxx”，不要抛堆栈。模型看到明确错误会自己换路，看到含糊输出会瞎猜。</li><li><strong>返回值控制体积</strong>：一万个 token 的原始日志塞回去，上下文直接爆。截断、摘要、分页，只给当前决策需要的部分。</li><li><strong>危险工具单独隔离</strong>：删除、支付、群发这类工具要么不给，要么加人工确认参数，确认前只返回“计划执行：……，等待确认”。</li></ul><h3 id="_4-失败兜底" tabindex="-1">4. 失败兜底 <a class="header-anchor" href="#_4-失败兜底" aria-label="Permalink to “4. 失败兜底”">​</a></h3><ul><li><strong>最大步数</strong>：超了就停，把已完成部分和当前状态报出来，绝不无限循环烧钱。</li><li><strong>成本上限</strong>：单任务 token 花费设预算，超了中断告警。Agent 的成本是指数型的，一道循环没拦住，一晚上能烧掉一个月订阅费。</li><li><strong>关键动作确认</strong>：不可逆操作先输出计划，人确认再执行——和自动化脚本同一条纪律。</li><li><strong>可恢复</strong>：每步记日志（做了什么、拿到什么），挂了能从断点看起，而不是从头重跑。</li><li><strong>输出带依据</strong>：涉及事实的结论，附上它依据的工具返回，方便你抽查，防止它一本正经地编。</li></ul><h3 id="_5-一个最小可用的例子" tabindex="-1">5. 一个最小可用的例子 <a class="header-anchor" href="#_5-一个最小可用的例子" aria-label="Permalink to “5. 一个最小可用的例子”">​</a></h3><p>拿“仓库日报”这个小任务走一遍：</p><ul><li><strong>目标</strong>：汇总某仓库今天的 commit 和 issue 变化，生成一段日报。</li><li><strong>工具</strong>：<code>list_commits(since)</code>、<code>list_issues(since)</code>、<code>send_message(text)</code>，就三个。</li><li><strong>循环</strong>：先调 list_commits → 再调 list_issues → 发现 issue 数量异常多时再按标签查一次 → 拼成日报 → 调 send_message → 输出“完成”。</li><li><strong>系统提示</strong>：写明“只汇报事实，不推测原因；调用超过 6 次仍没拼出日报就停下来报告卡住的原因”。</li><li><strong>兜底</strong>：最大 10 步；send_message 是对外动作，加人工确认，先打印日报内容，你点头才发。</li></ul><p>结构就这么朴素：没有向量库、没有多 Agent 协作、没有框架炫技。等这个小循环稳定了，再加工具、加分支才有意义。</p><h3 id="_6-什么时候该退回工作流" tabindex="-1">6. 什么时候该退回工作流 <a class="header-anchor" href="#_6-什么时候该退回工作流" aria-label="Permalink to “6. 什么时候该退回工作流”">​</a></h3><p>出现这些信号，说明这个任务不该用 Agent：</p><ul><li>步骤其实每次都差不多——写死比让它自己选更稳定。</li><li>出错代价高、需要可预测的执行路径——工作流的每一步都能加断言。</li><li>你在反复调提示词“求”它别跑偏，调了十几次还是不稳——不是提示词问题，是任务不适合。</li></ul><p>先用工作流把任务跑稳，只把真正需要“随机应变”的那一小段包成 Agent 内嵌进去，往往是更务实的架构。</p><h2 id="关键要点" tabindex="-1">关键要点 <a class="header-anchor" href="#关键要点" aria-label="Permalink to “关键要点”">​</a></h2><ul><li>Agent = 模型 + 工具 + 循环；能提前写死流程的用工作流，需要运行时决策的才用 Agent。</li><li>最小可用 Agent：单一目标、两三个清晰工具、带步数上限的循环、一份系统提示。</li><li>工具描述像说明书，返回值带明确错误、控制体积，危险工具隔离或加确认。</li><li>兜底四件套：最大步数、成本预算、危险动作人工确认、逐步日志可恢复。</li><li>个人场景目标要小，宁可搭五个小 Agent，不要搭一个“全能管家”。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>个人搭 Agent 的门槛其实在认知不在代码：理解它只是“带工具的循环”，理解工作流和 Agent 的分界，理解工具接口的质量决定 Agent 的下限。从一个目标极小的任务起步，把步数、成本、危险动作三道闸装好，跑通一个再扩第二个。智能体的“智能”不在模型有多强，在于你给它划的边界有多清楚。</p>',28)])])}const p=a(l,[["render",r]]);export{_ as __pageData,p as default};
